<script setup>
import {ref} from 'vue';import axios from 'axios';import {message} from '../art';import StudySheet from './StudySheet.vue';
const props=defineProps({question:Object}),sheet=ref(null),category=ref('unclear'),details=ref(''),busy=ref(false),status=ref(''),sent=ref(false),failed=ref(false);
async function send(){busy.value=true;status.value='';failed.value=false;try{const r=await axios.post('/questions/'+props.question.id+'/report',{category:category.value,details:details.value,version:props.question.version},{timeout:20000});status.value=r.data.message;sent.value=true;details.value=''}catch(e){status.value=message(e);failed.value=true}finally{busy.value=false}}
function open(){sent.value=false;status.value='';failed.value=false;sheet.value.open()}
</script>
<template><div class="report-question"><button @click="open">Report a problem</button><StudySheet ref="sheet" title="Report a problem" :busy="busy"><p class="field-help">{{question.id}} · version {{question.version}}. Your report is attached to this version.</p><form v-if="!sent" @submit.prevent="send"><label>Problem<select v-model="category" :disabled="busy"><option value="unclear">Unclear question</option><option value="answer">Disputed answer</option><option value="reference">Outdated reference</option><option value="typo">Typo</option></select></label><label>What should we review?<textarea v-model="details" :disabled="busy" required minlength="5" maxlength="3000" rows="5"></textarea></label><button class="primary" :disabled="busy">{{busy?'Sending…':'Send report'}}</button></form><p :class="{error:failed}" :role="failed?'alert':'status'">{{status}}</p></StudySheet></div></template>
